const alert = $input.first().json.body;
const srcIp = alert.data?.srcip || 'unknown';
const dstIp = alert.data?.dstip || 'unknown';
const portsScanned = alert.data?.ports_scanned || 'multiple';

const incident = {
  incident_id: `INC-${Date.now()}`,
  title: `Port Scan Detected: ${srcIp}`,
  description: `TCP Port Scan from ${srcIp} targeting ${dstIp}. Multiple rejected connections detected within 60 seconds.`,
  severity: 'HIGH',
  confidence: 85,
  source_ip: srcIp,
  target_ip: dstIp,
  mitre_technique: 'T1046 - Network Service Scanning',
  kill_chain_phase: 'Reconnaissance',
  wazuh_rule_id: alert.rule?.id,
  timestamp: new Date().toISOString(),
  status: 'OPEN',
  assigned_to: 'SOC_TEAM_ALPHA',
  evidence: [
    `${alert.rule?.description}`,
    `Source: ${srcIp}`,
    `Target: ${dstIp}`,
    `Connection State: REJ/S0 (rejected)`,
    `Frequency: 25+ connections in 60s window`
  ]
};

return [{ json: incident }];
